;===================================================================================
; hdr.asm - AUTO-GENERATED by snes_rules from your Makefile variables.
; Do not edit by hand! changes are overwritten on the next `make`.
; To hand-write your own, set AUTOHDR := 0 in your Makefile and ship hdr.asm yourself.
;===================================================================================

; HIROM / FASTROM definitions
.DEFINE HIROM 1
.DEFINE FASTROM 1

.ifdef HIROM                    ;   ==HiRom==

.MEMORYMAP                      ; Begin describing the system architecture.
  SLOTSIZE $10000               ; The slot is $10000 bytes in size. More details on slots later.
  DEFAULTSLOT 0                 ; There's only 1 slot in SNES, there are more in other consoles.
  SLOT 0 $0000                  ; Defines Slot 0's starting address.
  SLOT 1 $0 $2000               ; Used for low RAM allocation
  SLOT 2 $2000 $E000            ; Used for RAM allocation
  SLOT 3 $0 $10000              ; Used for global RAM allocation
  SLOT 4 $6000                  ; Used for SRAM storage.
.ENDME                          ; End MemoryMap definition

.ROMBANKSIZE $10000             ; Every ROM bank is 64 KBytes in size

.else                           ;   ==LoRom==

.MEMORYMAP                      ; Begin describing the system architecture.
  SLOTSIZE $8000                ; The slot is $8000 bytes in size. More details on slots later.
  DEFAULTSLOT 0                 ; There's only 1 slot in SNES, there are more in other consoles.
  SLOT 0 $8000                  ; Defines Slot 0's starting address.
  SLOT 1 $0 $2000               ; Used for low RAM allocation
  SLOT 2 $2000 $E000            ; Used for RAM allocation
  SLOT 3 $0 $10000              ; Used for global RAM allocation and data storage
.ENDME                          ; End MemoryMap definition

.ROMBANKSIZE $8000              ; Every ROM bank is 32 KBytes in size

.endif

; MSU-1 build: all new-char chr streams live in kof98-snes.msu, so the
; ROM itself fits back in 8 MiB again.
.IFDEF BIGROM
.ROMBANKS 256
.ELSE
.ROMBANKS 128
.ENDIF
.EXHIROM                              ; 64 Mbit: banks 64+ live at $00-3F

.SNESHEADER
  ID "SNES"
  NAME "KOF98 SNESFEST"
  FASTROM
  CARTRIDGETYPE $00
.IFDEF BIGROM
  ROMSIZE $0E
.ELSE
  ROMSIZE $0D
.ENDIF
  ; $0D also covers the 8 MiB image; MSU-1 data is external to the map.
  SRAMSIZE $00
  COUNTRY $01
  LICENSEECODE $00
  VERSION $00
.ENDSNES

; ExHiROM: CPU vectors are fetched from $00:FFxx, which maps to file bank
; 64 (upper 4MB).  The real code lives at $C0+, so Boot64's stubs (in
; src/snes/boot64.asm) trampoline through JML.
.SNESNATIVEVECTOR               ; Define Native Mode interrupt vector table
  COP StubEmpty
  BRK StubEmpty
  ABORT StubEmpty
  NMI StubNMI
  IRQ StubEmpty
.ENDNATIVEVECTOR

.SNESEMUVECTOR                  ; Define Emulation Mode interrupt vector table
  COP StubEmpty
  ABORT StubEmpty
  NMI StubEmpty
  RESET StubReset
  IRQBRK StubEmpty
.ENDEMUVECTOR


.ifdef FASTROM
.ifdef HIROM
    .BASE $C0
.else
    .BASE $80
.endif
.else
.ifdef HIROM
    .BASE $40
.endif
.endif